<template>
  <main class="cash">
    <header><div><small>FINANCEIRO</small><h1>Caixas do restaurante</h1><p>Cadastro, operadores, sessões e movimentações.</p></div><Button label="Novo caixa" icon="pi pi-plus" @click="openCreate" /></header>
    <div v-if="loading" class="card">Carregando...</div>
    <template v-else-if="!selected">
      <Message v-if="operatorSession" severity="info" :closable="false"><div class="session-message"><span>Você já possui uma sessão em andamento no <b>{{ operatorStation?.name || 'caixa atual' }}</b>.</span><Button v-if="operatorStation" label="Ir para meu caixa" icon="pi pi-arrow-right" size="small" text @click="selectStation(operatorStation)" /></div></Message>
      <div class="stations"><article v-for="station in stations" :key="station.id" :class="['station', `station--${stationTone(station)}`]" role="button" tabindex="0" @click="selectStation(station)" @keydown.enter="selectStation(station)"><span><b>{{ station.name }}</b><small>{{ station.code }} · {{ station.operator_names.length }} operador(es)</small></span><div class="station-actions"><Tag :value="station.current_session ? statusLabel(station.current_session.status) : 'Fechado'" :severity="station.current_session?.status==='pending_manager_approval' ? 'warning' : station.current_session ? 'success' : 'danger'" /><Button icon="pi pi-pencil" aria-label="Editar caixa" severity="secondary" outlined size="small" @click.stop="prepareEdit(station)" /><Button v-if="station.current_session?.status==='pending_manager_approval'" label="Resolver" icon="pi pi-exclamation-triangle" severity="warning" size="small" @click.stop="selectStation(station)" /><Button v-else-if="station.current_session" label="Fechar caixa" icon="pi pi-lock" severity="danger" size="small" @click.stop="prepareClose(station)" /><Button v-else label="Abrir caixa" icon="pi pi-lock-open" severity="success" size="small" :disabled="!!operatorSession" @click.stop="prepareOpen(station)" /></div></article></div>
      <div v-if="!stations.length" class="card">Nenhum caixa cadastrado neste restaurante.</div>
    </template>
    <template v-else>
      <Button label="Voltar aos caixas" icon="pi pi-arrow-left" text class="back" @click="selected=null;current=null" />
      <section class="hero"><div><small>{{ selected.code }}</small><h2>{{ selected.name }}</h2><p>Operadores: {{ selected.operator_names.join(', ') || 'Todos os operadores' }}</p></div><div class="station-actions"><Tag :value="current ? statusLabel(current.status) : 'Fechado'" :severity="current?.status==='pending_manager_approval' ? 'warning' : current ? 'success' : 'danger'" /><Button label="Editar" icon="pi pi-pencil" severity="secondary" outlined @click="prepareEdit(selected)" /><Button v-if="current?.status==='pending_manager_approval'" label="Aprovar fechamento" icon="pi pi-check" severity="warning" @click="prepareRegisterApproval" /><Button v-else-if="current" label="Fechar caixa" icon="pi pi-lock" severity="danger" @click="prepareClose(selected)" /><Button v-else label="Abrir caixa" icon="pi pi-lock-open" severity="success" :disabled="!!operatorSession" @click="prepareOpen(selected)" /></div></section>
      <template v-if="current">
        <Message v-if="current.status==='pending_manager_approval'" severity="warn" :closable="false"><div class="divergence"><b>Divergência {{ current.pending_operation==='opening' ? 'na abertura' : 'no fechamento' }} — é necessária aprovação gerencial.</b><ul v-if="current.difference_amount!==undefined"><li>Valor esperado: <strong>{{ money(current.expected_amount) }}</strong></li><li>Valor contado: <strong>{{ money(current.actual_amount) }}</strong></li><li>Diferença: <strong :class="Number(current.difference_amount)<0 ? 'diff-neg' : 'diff-pos'">{{ differenceLabel(current.difference_amount) }}</strong></li></ul><p v-if="current.notes">Observação: {{ current.notes }}</p></div></Message>
        <section class="card cash-actions"><div><h3>Ações do caixa</h3><small>Registre entradas e retiradas de dinheiro desta sessão.</small></div><div><Button label="Suprimento" icon="pi pi-plus-circle" severity="success" :disabled="current.status!=='open'" @click="prepareMovement('supply')" /><Button label="Sangria" icon="pi pi-minus-circle" severity="danger" :disabled="current.status!=='open'" @click="prepareMovement('withdrawal')" /></div></section>
        <section class="card movements"><div class="table-header"><div><h3>Histórico de movimentações</h3><small>Consulte entradas e saídas registradas nesta abertura.</small></div><IconField icon-position="left"><InputIcon class="pi pi-search" /><InputText v-model="movementFilters.global.value" placeholder="Filtrar movimentações" /></IconField></div><DataTable v-model:filters="movementFilters" :value="current.movements" paginator :rows="10" :rows-per-page-options="[5,10,20,50]" sort-field="created_at" :sort-order="-1" :global-filter-fields="['movement_type','reason','status','operator_name']" striped-rows responsive-layout="scroll"><template #empty>Nenhuma movimentação encontrada.</template><Column field="created_at" header="Data e hora" sortable><template #body="{data}">{{ date(data.created_at) }}</template></Column><Column field="movement_type" header="Movimento" sortable><template #body="{data}">{{ movementLabel(data.movement_type) }}</template></Column><Column field="reason" header="Motivo" sortable><template #body="{data}">{{ data.reason || '—' }}</template></Column><Column field="amount" header="Valor" sortable><template #body="{data}"><strong>{{ money(data.amount) }}</strong></template></Column><Column field="status" header="Status" sortable><template #body="{data}"><div class="status-action"><Tag :value="data.status==='pending'?'Pendente':'Confirmada'" :severity="data.status==='pending'?'warning':'success'" /><Button v-if="data.status==='pending'" label="Aprovar" icon="pi pi-check" size="small" text @click="prepareApproval(data)" /></div></template></Column></DataTable></section>
      </template>
      <section class="card sessions"><div class="table-header"><div><h3>Histórico de aberturas e fechamentos</h3><small>Consulte as sessões abertas e fechadas deste caixa.</small></div><IconField icon-position="left"><InputIcon class="pi pi-search" /><InputText v-model="sessionFilters.global.value" placeholder="Filtrar sessões" /></IconField></div><DataTable v-model:filters="sessionFilters" :value="selected.recent_sessions" paginator :rows="10" :rows-per-page-options="[5,10,20,50]" sort-field="opened_at" :sort-order="-1" :global-filter-fields="['operator','status']" striped-rows responsive-layout="scroll"><template #empty>Nenhuma sessão encontrada.</template><Column field="operator" header="Operador" sortable /><Column field="opened_at" header="Abertura" sortable><template #body="{data}">{{ date(data.opened_at) }}</template></Column><Column field="closed_at" header="Fechamento" sortable><template #body="{data}">{{ date(data.closed_at) }}</template></Column><Column field="opening_amount" header="Valor de abertura" sortable><template #body="{data}">{{ money(data.opening_amount) }}</template></Column><Column field="actual_amount" header="Valor de fechamento" sortable><template #body="{data}"><strong>{{ money(data.actual_amount) }}</strong></template></Column><Column field="status" header="Status" sortable><template #body="{data}"><Tag :value="statusLabel(data.status)" :severity="data.status==='pending_manager_approval' ? 'warning' : data.status==='open' ? 'success' : data.status==='closed' ? 'info' : 'danger'" /></template></Column></DataTable></section>
    </template>
    <Dialog v-model:visible="showCreate" :header="editingStation ? 'Editar caixa' : 'Cadastrar caixa'" modal :style="{width:'480px'}"><div class="form"><div class="field"><label for="cash-name">Nome do caixa</label><small>Nome usado para identificar este caixa no restaurante.</small><InputText id="cash-name" v-model="form.name" placeholder="Ex.: Caixa principal" /></div><div class="field"><label for="cash-code">Código</label><small>Identificador único e curto para facilitar a localização.</small><InputText id="cash-code" v-model="form.code" placeholder="Ex.: CX-01" /></div><div class="field"><label for="cash-operators">Operadores vinculados</label><small>Selecione os usuários autorizados a abrir e movimentar este caixa.</small><MultiSelect v-model="form.operators" input-id="cash-operators" :options="users" option-label="display_name" option-value="id" placeholder="Selecione os operadores" display="chip" /></div><div class="field"><label for="cash-limit">Limite de numerário</label><small>Valor máximo recomendado de dinheiro físico neste caixa.</small><InputNumber v-model="form.cash_limit" input-id="cash-limit" mode="currency" currency="BRL" locale="pt-BR" placeholder="R$ 0,00" /></div><div v-if="editingStation" class="edit-actions"><Button label="Excluir caixa" icon="pi pi-trash" severity="danger" outlined :disabled="!!editingStation?.current_session" @click="deleteFromEdit" /><Button label="Salvar alterações" icon="pi pi-check" :loading="saving" @click="saveStation" /></div><Button v-else label="Salvar caixa" icon="pi pi-plus" :loading="saving" @click="saveStation" /></div></Dialog>
    <Dialog v-model:visible="showDelete" header="Excluir caixa" modal :style="{width:'420px'}"><div class="form delete-confirm"><i class="pi pi-exclamation-triangle" /><div><h3>Excluir {{ actionStation?.name }}?</h3><p>O caixa será removido da lista. O histórico de movimentações e fechamentos será preservado.</p></div><div class="dialog-actions"><Button label="Cancelar" severity="secondary" outlined @click="showDelete=false" /><Button label="Excluir caixa" icon="pi pi-trash" severity="danger" :loading="saving" @click="deleteStation" /></div></div></Dialog>
    <Dialog v-model:visible="showOpen" :header="`Abrir ${actionStation?.name || 'caixa'}`" modal :style="{width:'440px'}"><div class="form"><div class="field"><label for="opening-amount">Valor de abertura</label><small>Informe o total de dinheiro físico contado antes de iniciar as vendas.</small><InputNumber v-model="opening.amount" input-id="opening-amount" mode="currency" currency="BRL" locale="pt-BR" /></div><div class="field"><label for="opening-notes">Observação</label><small>Registre alguma informação relevante sobre a abertura, se necessário.</small><Textarea id="opening-notes" v-model="opening.notes" placeholder="Observação da abertura" rows="3" /></div><Button label="Confirmar abertura" icon="pi pi-lock-open" severity="success" :loading="saving" @click="openRegister" /></div></Dialog>
    <Dialog v-model:visible="showClose" :header="`Fechar ${actionStation?.name || 'caixa'}`" modal :style="{width:'440px'}"><div class="form"><div class="field"><label for="closing-amount">Valor contado</label><small>Informe o total de dinheiro físico contado. O valor esperado permanece oculto durante o fechamento.</small><InputNumber v-model="closing.amount" input-id="closing-amount" mode="currency" currency="BRL" locale="pt-BR" /></div><div class="field"><label for="closing-notes">Observação</label><small>Informe ocorrências ou justificativas relacionadas ao fechamento.</small><Textarea id="closing-notes" v-model="closing.notes" placeholder="Observação do fechamento" rows="3" /></div><Button label="Confirmar fechamento" icon="pi pi-lock" severity="danger" :loading="saving" @click="closeRegister" /></div></Dialog>
    <Dialog v-model:visible="showMovement" :header="movement.type==='withdrawal' ? 'Registrar sangria' : 'Registrar suprimento'" modal :style="{width:'440px'}"><div class="form"><Message :severity="movement.type==='withdrawal'?'warn':'info'" :closable="false">{{ movement.type==='withdrawal' ? 'A sangria ficará pendente até a aprovação de outro gerente.' : 'O suprimento será somado ao saldo esperado deste caixa.' }}</Message><div class="field"><label for="movement-amount">Valor</label><small>{{ movement.type==='withdrawal' ? 'Informe quanto será retirado do caixa.' : 'Informe quanto será adicionado ao caixa.' }}</small><InputNumber v-model="movement.amount" input-id="movement-amount" mode="currency" currency="BRL" locale="pt-BR" /></div><div v-if="movement.type==='withdrawal'" class="field"><label for="movement-destination">Destino do dinheiro</label><small>Informe para onde o valor retirado será encaminhado.</small><InputText id="movement-destination" v-model="movement.destination" placeholder="Ex.: Cofre, banco ou tesouraria" /></div><div class="field"><label for="movement-reason">Motivo</label><small>Descreva por que esta movimentação está sendo realizada.</small><Textarea id="movement-reason" v-model="movement.reason" placeholder="Motivo obrigatório" rows="3" /></div><Button :label="movement.type==='withdrawal'?'Confirmar sangria':'Confirmar suprimento'" :icon="movement.type==='withdrawal'?'pi pi-minus-circle':'pi pi-plus-circle'" :severity="movement.type==='withdrawal'?'danger':'success'" :loading="saving" @click="addMovement" /></div></Dialog>
    <Dialog v-model:visible="showApproval" :header="movementToApprove ? 'Autorizar sangria' : 'Resolver divergência do fechamento'" modal :closable="!saving" :close-on-escape="!saving" :style="{width:'480px'}" @hide="resetApproval"><div class="form"><Message severity="warn" :closable="false"><div class="divergence"><b>{{ movementToApprove ? 'A sangria exige autorização gerencial.' : 'O caixa continuará bloqueado até a divergência ser aprovada.' }}</b><ul v-if="!movementToApprove && current"><li>Valor esperado: <strong>{{ money(current.expected_amount) }}</strong></li><li>Valor contado: <strong>{{ money(current.actual_amount) }}</strong></li><li>Diferença: <strong :class="Number(current.difference_amount)<0 ? 'diff-neg' : 'diff-pos'">{{ differenceLabel(current.difference_amount) }}</strong></li></ul><p v-if="!movementToApprove && current?.notes">Observação: {{ current.notes }}</p></div></Message><div class="field"><label for="approval-user">Usuário autorizador</label><small>Informe o usuário de um gerente, administrador ou proprietário autorizado.</small><InputText id="approval-user" v-model.trim="approval.username" autocomplete="off" placeholder="Usuário ou e-mail" /></div><div class="field"><label for="approval-password">Senha</label><small>A credencial será usada somente nesta autorização e descartada em seguida.</small><Password v-model="approval.password" input-id="approval-password" :feedback="false" toggle-mask autocomplete="new-password" placeholder="Senha do autorizador" /></div><div class="field"><label for="approval-reason">Justificativa gerencial</label><small>Registre o motivo desta autorização.</small><Textarea id="approval-reason" v-model="approval.reason" placeholder="Justificativa obrigatória" rows="3" /></div><Button :label="movementToApprove ? 'Autorizar sangria' : 'Aprovar e concluir fechamento'" icon="pi pi-shield" severity="success" :loading="saving" :disabled="!approval.username || !approval.password || !approval.reason.trim()" @click="approveOperation" /></div></Dialog>
  </main>
</template>
<script setup>
import {computed,onMounted,reactive,ref} from "vue";import {FilterMatchMode} from "primevue/api";import Button from "primevue/button";import Column from "primevue/column";import DataTable from "primevue/datatable";import Dialog from "primevue/dialog";import IconField from "primevue/iconfield";import InputIcon from "primevue/inputicon";import InputNumber from "primevue/inputnumber";import InputText from "primevue/inputtext";import Message from "primevue/message";import MultiSelect from "primevue/multiselect";import Password from "primevue/password";import Tag from "primevue/tag";import Textarea from "primevue/textarea";import {useToast} from "primevue/usetoast";import {api,closeTemporarySession,loginRequest,temporaryAuthenticatedPost} from "../services/api";import {normalizeApiError} from "../utils/apiError";
const toast=useToast(),stations=ref([]),users=ref([]),selected=ref(null),current=ref(null),operatorSession=ref(null),actionStation=ref(null),editingStation=ref(null),movementToApprove=ref(null),loading=ref(true),saving=ref(false),showCreate=ref(false),showOpen=ref(false),showClose=ref(false),showDelete=ref(false),showMovement=ref(false),showApproval=ref(false);const operatorStation=computed(()=>stations.value.find(station=>station.id===operatorSession.value?.cash_station));const movementFilters=ref({global:{value:null,matchMode:FilterMatchMode.CONTAINS}});const sessionFilters=ref({global:{value:null,matchMode:FilterMatchMode.CONTAINS}});const form=reactive({name:"",code:"",operators:[],cash_limit:0,is_active:true}),opening=reactive({amount:0,notes:""}),closing=reactive({amount:0,notes:""}),movement=reactive({type:"supply",amount:0,reason:"",destination:""}),approval=reactive({username:"",password:"",reason:""});
async function load(){loading.value=true;try{const[a,b,session]=await Promise.all([api.get("/cash-stations/",{params:{page_size:100}}),api.get("/users/",{params:{page_size:200}}),api.get("/cash-register/current/").catch(error=>error.response?.status===404?{data:null}:Promise.reject(error))]);stations.value=a.data.results||a.data;users.value=(b.data.results||b.data).map(u=>({...u,display_name:u.full_name||u.username}));operatorSession.value=session.data;}finally{loading.value=false;}}
async function run(fn){saving.value=true;try{const response=await fn();await load();if(selected.value){const fresh=stations.value.find(s=>s.id===selected.value.id);if(fresh)await selectStation(fresh);else{selected.value=null;current.value=null;}}return response||true;}catch(e){toast.add({severity:"error",summary:"Operação não concluída",detail:normalizeApiError(e).message,life:5000});return false;}finally{saving.value=false;}}
async function selectStation(station){selected.value=station;if(!station.current_session){current.value=null;return;}try{const{data}=await api.get(`/cash-register/${station.current_session.id}/`);current.value=data;}catch{current.value=null;}}
function resetForm(){Object.assign(form,{name:"",code:"",operators:[],cash_limit:0,is_active:true});}function resetApproval(){Object.assign(approval,{username:"",password:"",reason:""});movementToApprove.value=null;}function openCreate(){editingStation.value=null;resetForm();showCreate.value=true;}function prepareEdit(station){editingStation.value=station;Object.assign(form,{name:station.name,code:station.code,operators:[...(station.operators||[])],cash_limit:Number(station.cash_limit||0),is_active:station.is_active});showCreate.value=true;}function prepareDelete(station){actionStation.value=station;showDelete.value=true;}function deleteFromEdit(){const s=editingStation.value;showCreate.value=false;prepareDelete(s);}const saveStation=async()=>{const restaurant=localStorage.getItem("starchef-restaurant-scope"),payload={...form,...(restaurant?{restaurant}:{})};const ok=await run(()=>editingStation.value?api.patch(`/cash-stations/${editingStation.value.id}/`,payload):api.post("/cash-stations/",payload));if(ok)showCreate.value=false;};const deleteStation=async()=>{const deletedId=actionStation.value.id;if(await run(()=>api.delete(`/cash-stations/${deletedId}/`))){showDelete.value=false;if(selected.value?.id===deletedId){selected.value=null;current.value=null;}}};function prepareOpen(station){actionStation.value=station;opening.amount=0;opening.notes="";showOpen.value=true;}async function prepareClose(station){actionStation.value=station;await selectStation(station);if(current.value)showClose.value=true;}function prepareMovement(type){Object.assign(movement,{type,amount:0,reason:"",destination:""});showMovement.value=true;}function prepareApproval(item){resetApproval();movementToApprove.value=item;showApproval.value=true;}function prepareRegisterApproval(){resetApproval();showApproval.value=true;}const openRegister=async()=>{if(await run(()=>api.post("/cash-register/open/",{cash_station:actionStation.value.id,opening_amount:opening.amount,notes:opening.notes,device_identifier:navigator.userAgent})))showOpen.value=false;};const closeRegister=async()=>{const response=await run(()=>api.post(`/cash-register/${current.value.id}/close/`,{actual_amount:closing.amount,notes:closing.notes}));if(!response)return;showClose.value=false;if(response.data?.status==="pending_manager_approval"){current.value=response.data;prepareRegisterApproval();}};const addMovement=async()=>{if(await run(()=>api.post(`/cash-register/${current.value.id}/${movement.type}/`,{amount:movement.amount,reason:movement.reason,destination:movement.destination,source:movement.destination})))showMovement.value=false;};const approveOperation=async()=>{if(!approval.username||!approval.password||!approval.reason.trim())return;saving.value=true;let access="",refresh="";const approvingMovement=Boolean(movementToApprove.value);try{const login=await loginRequest({username:approval.username,password:approval.password},{temporary:true});access=login.data.access;refresh=login.data.refresh;const profile=login.data.user;if(!profile?.is_superuser&&!['admin','owner','manager'].includes(profile?.profile_type)){throw new Error("O usuário informado não possui permissão gerencial para autorizar esta operação.");}const payload={reason:approval.reason.trim(),...(movementToApprove.value?{movement:movementToApprove.value.id}:{})};await temporaryAuthenticatedPost(`/cash-register/${current.value.id}/approve/`,payload,access);showApproval.value=false;resetApproval();toast.add({severity:"success",summary:"Autorização concluída",detail:approvingMovement?"Sangria autorizada.":"Divergência aprovada e caixa fechado.",life:4000});await load();if(selected.value){const fresh=stations.value.find(s=>s.id===selected.value.id);if(fresh)await selectStation(fresh);}}catch(e){toast.add({severity:"error",summary:"Autorização não concluída",detail:e?.response?normalizeApiError(e).message:(e?.message||"Não foi possível autorizar a operação."),life:6000});}finally{await closeTemporarySession(access,refresh);approval.password="";saving.value=false;}};
const money=v=>Number(v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"}),date=v=>v?new Date(v).toLocaleString("pt-BR"):"—";const differenceLabel=v=>{const n=Number(v||0);const abs=money(Math.abs(n));return n<0?`${abs} (falta)`:n>0?`${abs} (sobra)`:`${abs} (sem diferença)`;};const statusLabel=s=>({open:"Aberto",pending_manager_approval:"Aguardando gerente",closed:"Fechado",closed_with_difference:"Fechado com diferença",blocked:"Bloqueado"}[s]||s);const movementLabel=t=>({opening:"Abertura",sale:"Venda em dinheiro",withdrawal:"Sangria",supply:"Suprimento",closing:"Fechamento",adjustment:"Ajuste",refund:"Estorno"}[t]||t);const stationTone=s=>s.current_session?(s.current_session.status==="pending_manager_approval"?"warn":"open"):"closed";onMounted(load);
</script>
<style scoped>
.cash{max-width:1100px;margin:auto;padding:28px;display:flex;flex-direction:column;gap:18px}
.cash header,.hero,.row,.station{display:flex;align-items:center;justify-content:space-between;gap:18px}
.cash header>div{display:flex;flex-direction:column;gap:6px}
.cash h1,.cash h2,.cash h3,.cash p{margin:0}
