.hero,.card{box-shadow:var(--shadow-sm)}
.station{text-align:left;cursor:pointer;border-left:3px solid var(--border-strong);transition:border-color var(--dur-fast) var(--ease-out),box-shadow var(--dur-fast) var(--ease-out),transform var(--dur-fast) var(--ease-out)}
.station:hover,.station:focus-visible{border-color:var(--brand-border);box-shadow:var(--shadow-md);transform:translateY(-2px)}
.station--open{border-left-color:var(--success)}
.station--warn{border-left-color:var(--warning)}
.station--closed{border-left-color:var(--border-strong)}
.station span,.row span{display:flex;flex-direction:column;gap:4px}
.station b{color:var(--text-strong);font:var(--weight-bold) 15px/1.2 var(--font-sans)}
.station-actions,.table-header,.dialog-actions{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}
.table-header>div,.cash-actions>div:first-child{display:flex;flex-direction:column;gap:4px}
.cash-actions>div:last-child,.status-action{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.card,.form{display:flex;flex-direction:column;gap:12px}
.form{padding-top:12px;gap:18px}
.edit-actions{display:flex;align-items:center;justify-content:space-between;gap:12px}
.field{display:flex;flex-direction:column;gap:6px}
.field label{font-weight:600;color:var(--text-strong)}
.field small{line-height:1.4}
.field :deep(.p-inputtext),.field :deep(.p-inputnumber),.field :deep(.p-multiselect),.field :deep(.p-inputtextarea),.field :deep(.p-password){width:100%}
.delete-confirm>i{align-self:center;font-size:2rem;color:var(--danger)}
.delete-confirm h3,.delete-confirm p{margin:0}
.delete-confirm>div{display:flex;flex-direction:column;gap:6px}
